/* 학습 해설
 * OF reserved 겹침검사·정렬뒤이웃범위
 * DTB예약메모리를고정배열과부팅allocator에연결하고정렬·범위선택·callback·장치연결목록·잠금·해제의원리와오류정책을원문에서읽습니다.
 * count2미만은넘기고배열을비교함수로정렬합니다. 각이웃에서this.base+size>next.base이면경고합니다. 같은끝/시작은겹침이아닙니다. 경고만하며자동복구나거부를수행하지않고모든겹친쌍을전부나열하는검사도아닙니다.
 * [0x1000,0x2000)와[0x2000,0x3000)의접촉을계산합니다. 긴범위안의여러짧은범위처럼이웃비교가모든pair보고와다르다는점을표시하고합overflow전제도확인합니다.
 */
static void __init __rmem_check_for_overlap(void)
{
	int i;

	if (reserved_mem_count < 2)
		return;

	sort(reserved_mem, reserved_mem_count, sizeof(reserved_mem[0]),
	     __rmem_cmp, NULL);
	for (i = 0; i < reserved_mem_count - 1; i++) {
		struct reserved_mem *this, *next;

		this = &reserved_mem[i];
		next = &reserved_mem[i + 1];

		if (this->base + this->size > next->base) {
			phys_addr_t this_end, next_end;

			this_end = this->base + this->size;
			next_end = next->base + next->size;
			pr_err("OVERLAP DETECTED!\n%s (%pa--%pa) overlaps with %s (%pa--%pa)\n",
			       this->name, &this->base, &this_end,
			       next->name, &next->base, &next_end);
		}
	}
}

