/* 학습 해설
 * OF reserved 장치연결기록·struct와intrusive list
 * DTB예약메모리를고정배열과부팅allocator에연결하고정렬·범위선택·callback·장치연결목록·잠금·해제의원리와오류정책을원문에서읽습니다.
 * 기록struct는dev,rmem과내부list_head를가집니다. listnode를별도관리상자없이기록안에넣는intrusivelist이며정적목록head와mutex가연결기록을보호합니다. reserved_mem의고정배열과장치별동적기록목록은서로다른자료구조입니다.
 * reserved_mem공유entry←여러dev기록→listhead그림을그립니다. listnode의소유struct와callback/release에서해제하는기록공간을구별합니다.
 */
struct rmem_assigned_device {
	struct device *dev;
	struct reserved_mem *rmem;
	struct list_head list;
};

static LIST_HEAD(of_rmem_assigned_device_list);
static DEFINE_MUTEX(of_rmem_assigned_device_mutex);

/**
 * of_reserved_mem_device_init_by_idx() - assign reserved memory region to
 *					  given device
 * @dev:	Pointer to the device to configure
 * @np:		Pointer to the device_node with 'reserved-memory' property
 * @idx:	Index of selected region
 *
 * This function assigns respective DMA-mapping operations based on reserved
 * memory region specified by 'memory-region' property in @np node to the @dev
 * device. When driver needs to use more than one reserved memory region, it
 * should allocate child devices and initialize regions by name for each of
 * child device.
 *
 * Returns error code or zero on success.
 */
int of_reserved_mem_device_init_by_idx(struct device *dev,
				       struct device_node *np, int idx)

