/* 학습 해설
 * OF reserved 장치index조회·입력과phandle
 * DTB예약메모리를고정배열과부팅allocator에연결하고정렬·범위선택·callback·장치연결목록·잠금·해제의원리와오류정책을원문에서읽습니다.
 * np/devNULL은EINVAL입니다. memory-region의idxphandle대상을찾고부재면ENODEV입니다. idx를이본문에서독립bounds검사하지않고of_parse_phandle에위임합니다. nodepointer를획득하면후속분기에서of_node_put으로참조를내립니다.
 * caller node와targetreservednode를다르게그립니다. NULL입력/대상부재/lookup실패를표로적고reference획득과put을각반환경로에연결합니다.
 */
int of_reserved_mem_device_init_by_idx(struct device *dev,
				       struct device_node *np, int idx)
{
	struct rmem_assigned_device *rd;
	struct device_node *target;
	struct reserved_mem *rmem;
	int ret;

	if (!np || !dev)
		return -EINVAL;

	target = of_parse_phandle(np, "memory-region", idx);
	if (!target)
		return -ENODEV;

	if (!of_device_is_available(target)) {
		of_node_put(target);
		return 0;
	}

	rmem = of_reserved_mem_lookup(target);
	of_node_put(target);

	if (!rmem || !rmem->ops || !rmem->ops->device_init)
		return -EINVAL;

