 * OF RESERVED_MEM 꺼짐·공유entry조회
 * 예약영역과장치연결의공개자료/함수pointer/빌드table선언/설정별fallback/첫영역wrapper의역할과호출조건을원문에연결합니다.
 * 설정꺼짐에서of_reserved_mem_lookup은staticinlinefallback입니다. reservedentry이름검색과공유pointer제공을하지않습니다. 결과는NULL입니다. 기능부재를caller가정상빈결과와혼동하지않도록반환정책을확인해야하며활성구현의동작을이stub으로증명하지않습니다.
 * enabledextern과disabledinline을같은이름의서로다른선언위치로비교합니다. NULL의caller처리와설정조건을주석달고다른header의ENODEVfallback과ENOSYS를혼동하지않습니다.
 */
static inline struct reserved_mem *of_reserved_mem_lookup(struct device_node *np)
{
	return NULL;
}
#endif

/**
 * of_reserved_mem_device_init() - assign reserved memory region to given device
 * @dev:	Pointer to the device to configure
 *
 * This function assigns respective DMA-mapping operations based on the first
 * reserved memory region specified by 'memory-region' property in device tree
 * node of the given device.
 *
 * Returns error code or zero on success.
 */
static inline int of_reserved_mem_device_init(struct device *dev)
{
	return of_reserved_mem_device_init_by_idx(dev, dev->of_node, 0);
}

#endif /* __OF_RESERVED_MEM_H */

