/* 학습 해설
 * OF 주소 bus interface·함수 pointer 전략
 * 버스별cell표현과rangeoffset을parent/CPU/DMA주소공간으로옮기고resourcebounds·PIO/MMIO접근·예약/해제를연결하는기술의원리와사용조건을읽습니다.
 * of_bus는 이름/주소 property 이름과 match/count_cells/map/translate/get_flags callback, flag_cells를 제공합니다. 공통 traversal이 버스별 주소 표현을 같은 interface로 다루는 전략 table입니다. 구현 함수가 같아도 flag cell 수와 property 선택이 달라져 해석이 달라집니다.
 * PCI/ISA/default-flags/default의 table을 함수와 연결합니다. bus-local주소, parent주소, CPU주소를 다른 공간으로 그리고 map의offset과translate의출력주소를 구별합니다.
 */
struct of_bus {
	const char	*name;
	const char	*addresses;
	int		(*match)(struct device_node *parent);
	void		(*count_cells)(struct device_node *child,
				       int *addrc, int *sizec);
	u64		(*map)(__be32 *addr, const __be32 *range,
				int na, int ns, int pna, int fna);
	int		(*translate)(__be32 *addr, u64 offset, int na);
	int		flag_cells;
	unsigned int	(*get_flags)(const __be32 *addr);
};

/*
 * Default translator (generic bus)
 */

static void of_bus_default_count_cells(struct device_node *dev,
				       int *addrc, int *sizec)
{
	if (addrc)
		*addrc = of_n_addr_cells(dev);
	if (sizec)
		*sizec = of_n_size_cells(dev);
}

