/* 학습 해설
 * OF 기본 range map·half-open구간과offset
 * 버스별cell표현과rangeoffset을parent/CPU/DMA주소공간으로옮기고resourcebounds·PIO/MMIO접근·예약/해제를연결하는기술의원리와사용조건을읽습니다.
 * childbase cp,범위크기s,device주소da를cell에서읽습니다. da<cp또는da>=cp+s이면OF_BAD_ADDR,정상은da-cp입니다. flagcells는숫자해석에서빼고size는child+parent주소뒤에서읽습니다. cp+s의모든overflow를별도guard하는본문은아닙니다.
 * cp8/size16에서da10은offset2,da24는부재를계산합니다. 작은유효범위36,465조건의독립검산과모든u64범위안전성의차이를표시합니다.
 */
static u64 of_bus_default_map(__be32 *addr, const __be32 *range,
		int na, int ns, int pna, int fna)
{
	u64 cp, s, da;

	cp = of_read_number(range + fna, na - fna);
	s  = of_read_number(range + na + pna, ns);
	da = of_read_number(addr + fna, na - fna);

	pr_debug("default map, cp=%llx, s=%llx, da=%llx\n", cp, s, da);

	if (da < cp || da >= (cp + s))
		return OF_BAD_ADDR;
	return da - cp;
}

static int of_bus_default_translate(__be32 *addr, u64 offset, int na)
{
	u64 a = of_read_number(addr, na);
	memset(addr, 0, na * 4);
	a += offset;
	if (na > 1)
		addr[na - 2] = cpu_to_be32(a >> 32);
	addr[na - 1] = cpu_to_be32(a & 0xffffffffu);

	return 0;

