 * OF 기본 flags·메모리와명시flagcell
 * 버스별cell표현과rangeoffset을parent/CPU/DMA주소공간으로옮기고resourcebounds·PIO/MMIO접근·예약/해제를연결하는기술의원리와사용조건을읽습니다.
 * default-flags는첫cell을숫자로읽어flags로사용합니다. 일반default의get_flags는주소인자를사용하지않고IORESOURCE_MEM입니다. flagcell과주소숫자를분리하는버스규약이며flags자료가존재한다고모든장치동작을인증하지않습니다.
 * 첫cell0x55의flags조회와일반MEMfallback을비교합니다. generic버스주소3cell에서flag1을제외한숫자부분과resourceflags의의미를따로표시합니다.
 */
static unsigned int of_bus_default_flags_get_flags(const __be32 *addr)
{
	return of_read_number(addr, 1);
}

static unsigned int of_bus_default_get_flags(const __be32 *addr)
{
	return IORESOURCE_MEM;
}

static u64 of_bus_default_flags_map(__be32 *addr, const __be32 *range, int na,
				    int ns, int pna, int fna)
{
	/* Check that flags match */
	if (*addr != *range)
		return OF_BAD_ADDR;

	return of_bus_default_map(addr, range, na, ns, pna, fna);
}

static int of_bus_default_flags_translate(__be32 *addr, u64 offset, int na)
{
	/* Keep "flags" part (high cell) in translated address */
	return of_bus_default_translate(addr + 1, offset, na - 1);
}

