 * 첫wordbits24..25의spacecode1은IO,2는MEM,3은MEM|MEM_64입니다. bit30은PREFETCH를추가합니다. 같은u32안의flag와주소/BARmetadata가버스규약으로나뉘며CONFIG_PCI의guard도있습니다.
 * spacecode0..3×prefetch0/1의실제8조건을읽습니다. 64bitMEM도일반MEMbit를포함하고prefetch는주소범위자체가아니라는점을표시합니다.
 */
static unsigned int of_bus_pci_get_flags(const __be32 *addr)
{
	unsigned int flags = 0;
	u32 w = be32_to_cpup(addr);

	if (!IS_ENABLED(CONFIG_PCI))
		return 0;

	switch((w >> 24) & 0x03) {
	case 0x01:
		flags |= IORESOURCE_IO;
		break;
	case 0x02: /* 32 bits */
		flags |= IORESOURCE_MEM;
		break;

	case 0x03: /* 64 bits */
		flags |= IORESOURCE_MEM | IORESOURCE_MEM_64;
		break;
	}
