 * OF PCI bus선택·type와pcie이름fallback
 * 버스별cell표현과rangeoffset을parent/CPU/DMA주소공간으로옮기고resourcebounds·PIO/MMIO접근·예약/해제를연결하는기술의원리와사용조건을읽습니다.
 * device_type pci/pciex/vci/ht를match하고없어도이름pcie를경고와함께허용할수있습니다. 첫정상match뒤논리OR단락평가로다른검사를생략할수있습니다. PCIbus선택과실제PCI장치enumeration은다른단계입니다.
 * 네type과pcie이름fallback을표로적습니다. warning-once의목적과matchfunction의정책을읽고잘못된모든DTB형식을복구한다는설명으로확대하지않습니다.
 */
static int of_bus_pci_match(struct device_node *np)
{
	/*
 	 * "pciex" is PCI Express
	 * "vci" is for the /chaos bridge on 1st-gen PCI powermacs
	 * "ht" is hypertransport
	 *
	 * If none of the device_type match, and that the node name is
	 * "pcie", accept the device as PCI (with a warning).
	 */
	return of_node_is_type(np, "pci") || of_node_is_type(np, "pciex") ||
		of_node_is_type(np, "vci") || of_node_is_type(np, "ht") ||
		of_node_is_pcie(np);
}

