/* 학습 해설
 * OF range index선택·parser순회
 * 버스별cell표현과rangeoffset을parent/CPU/DMA주소공간으로옮기고resourcebounds·PIO/MMIO접근·예약/해제를연결하는기술의원리와사용조건을읽습니다.
 * parserinit이실패하면그오류를반환합니다. parser가제공하는range를순회해index번째를resource로바꾸고없으면ENOENT입니다. parser가연속entry를합칠수있어index를원본rawtuple번호와항상같다고판정하지않습니다.
 * raw연속두entry가하나의range로합쳐지는뒤parser원리를연결합니다. index와순회결과,init실패와부재를따로주석달아봅니다.
 */
int of_range_to_resource(struct device_node *np, int index, struct resource *res)
{
	int ret, i = 0;
	struct of_range_parser parser;
	struct of_range range;

	ret = of_range_parser_init(&parser, np);
	if (ret)
		return ret;

	for_each_of_range(&parser, &range)
		if (i++ == index)
			return of_pci_range_to_resource(&range, np, res);

	return -ENOENT;
}
EXPORT_SYMBOL(of_range_to_resource);

