/* 학습 해설
 * OF ISA 규약·이름cell폭과타입bit
 * 버스별cell표현과rangeoffset을parent/CPU/DMA주소공간으로옮기고resourcebounds·PIO/MMIO접근·예약/해제를연결하는기술의원리와사용조건을읽습니다.
 * ISA는이름isa로match,주소2/size1cell을사용합니다. 첫cellbit0의IO/MEM타입이addr/range에서다르면BAD,정상은기본map입니다. get_flags도같은bit0으로IO또는MEM을선택합니다.
 * 주소flag1과숫자10,rangeflag1/base8의offset2및flag0불일치를검산합니다. PCI의bits24..25와ISA의bit0의다른표현을표로적습니다.
 */
static u64 of_bus_isa_map(__be32 *addr, const __be32 *range, int na, int ns,
		int pna, int fna)
{
	/* Check address type match */
	if ((addr[0] ^ range[0]) & cpu_to_be32(1))
		return OF_BAD_ADDR;

	return of_bus_default_map(addr, range, na, ns, pna, fna);
}

static unsigned int of_bus_isa_get_flags(const __be32 *addr)
{
	unsigned int flags = 0;
	u32 w = be32_to_cpup(addr);

	if (w & 1)
		flags |= IORESOURCE_IO;
	else
		flags |= IORESOURCE_MEM;
	return flags;
}

static int of_bus_default_flags_match(struct device_node *np)
{
	return of_bus_n_addr_cells(np) == 3;
}

