/* 학습 해설
 * OF bus table우선순위·nullmatchfallback
 * 버스별cell표현과rangeoffset을parent/CPU/DMA주소공간으로옮기고resourcebounds·PIO/MMIO접근·예약/해제를연결하는기술의원리와사용조건을읽습니다.
 * of_busses는선택PCI→ISA→default-flags→default순서입니다. default-flags는busaddresscell3을match하고마지막default의matchNULL은무조건선택됩니다. table순서가첫match우선정책이며callback종류만으로순서를바꿔도같다고판정하지않습니다.
 * 동시에일반3cell과PCItype를만족하는node의첫선택을예측합니다. 마지막fallback이정상종료를제공하고BUG경로는그계약이깨졌을때라는점을표시합니다.
 */
static struct of_bus *of_match_bus(struct device_node *np)
{
	int i;

	for (i = 0; i < ARRAY_SIZE(of_busses); i++)
		if (!of_busses[i].match || of_busses[i].match(np))
			return &of_busses[i];
	BUG();
	return NULL;
}

static int of_empty_ranges_quirk(struct device_node *np)
{
	if (IS_ENABLED(CONFIG_PPC)) {
		/* To save cycles, we cache the result for global "Mac" setting */
		static int quirk_state = -1;

		/* PA-SEMI sdc DT bug */
		if (of_device_is_compatible(np, "1682m-sdc"))
			return true;

		/* Make quirk cached */
		if (quirk_state < 0)
			quirk_state =
				of_machine_is_compatible("Power Macintosh") ||
				of_machine_is_compatible("MacRISC");

