/* 학습 해설
 * OF DMA parent·interconnect dma-mem선택
 * 버스별cell표현과rangeoffset을parent/CPU/DMA주소공간으로옮기고resourcebounds·PIO/MMIO접근·예약/해제를연결하는기술의원리와사용조건을읽습니다.
 * interconnect-names에서dma-memindex를찾고interconnects/#interconnect-cells로대상을해석합니다. 이름부재/파싱실패는일반parentfallback입니다. DMA경로가tree의단순parent와다를수있는기술이며callback으로공통translation에제공됩니다.
 * 일반busparent와DMAinterconnectparent를두화살표로그립니다. fallback조건과of_get_next_dma_parent의이전nodeput을연결하고전체interconnectdriver실행으로확대하지않습니다.
 */
struct device_node *__of_get_dma_parent(const struct device_node *np)
{
	struct of_phandle_args args;
	int ret, index;

	index = of_property_match_string(np, "interconnect-names", "dma-mem");
	if (index < 0)
		return of_get_parent(np);

	ret = of_parse_phandle_with_args(np, "interconnects",
					 "#interconnect-cells",
					 index, &args);
	if (ret < 0)
		return of_get_parent(np);

	return of_node_get(args.np);
}
#endif

