 * 일반ranges/일반parent와DMA-ranges/DMAparent의인자를비교합니다. 주소변환과DMAmapping/cache동기화의다른단계를주석으로적습니다.
 */
u64 of_translate_dma_address(struct device_node *dev, const __be32 *in_addr)
{
	struct device_node *host;
	u64 ret;

	ret = __of_translate_address(dev, __of_get_dma_parent,
				     in_addr, "dma-ranges", &host);

	if (host) {
		of_node_put(host);
		return OF_BAD_ADDR;
	}

	return ret;
}
EXPORT_SYMBOL(of_translate_dma_address);

/**
 * of_translate_dma_region - Translate device tree address and size tuple
 * @dev: device tree node for which to translate
 * @prop: pointer into array of cells
 * @start: return value for the start of the DMA range
 * @length: return value for the length of the DMA range
 *
 * Returns a pointer to the cell immediately following the translated DMA region.
 */

annotated:
/* 학습 해설
 * OF DMA tuple읽기·선택output과다음cursor
 * 버스별cell표현과rangeoffset을parent/CPU/DMA주소공간으로옮기고resourcebounds·PIO/MMIO접근·예약/해제를연결하는기술의원리와사용조건을읽습니다.
 * DMAparent가없거나주소변환BAD이면NULL입니다. parent의address/sizecell수로주소와size를읽고start/length가있을때대입한뒤prop+na+ns를반환합니다. size_t로의길이대입에서모든축소변환경계를별도검사하는본문은아닙니다.
 * 주소2,size1의3cell소비와다음pointer를그립니다. NULL실패에서outparameter를정상값처럼사용하지않고주소/size표현폭계약을따로확인합니다.
 */
const __be32 *of_translate_dma_region(struct device_node *dev, const __be32 *prop,
				      phys_addr_t *start, size_t *length)
{
	struct device_node *parent __free(device_node) = __of_get_dma_parent(dev);
	u64 address, size;
	int na, ns;

	if (!parent)
		return NULL;

	na = of_bus_n_addr_cells(parent);
	ns = of_bus_n_size_cells(parent);

	address = of_translate_dma_address(dev, prop);
	if (address == OF_BAD_ADDR)
		return NULL;

	size = of_read_number(prop + na, ns);

	if (start)
		*start = address;

	if (length)
		*length = size;

	return prop + na + ns;

